1	#!/usr/bin/env node
2	/**
3	 * Node.js port of /workspace/dataset/construct/test17.py.
4	 *
5	 * The Python original builds seven little-endian fields with `construct` and
6	 * prints each resulting bytes object. This file keeps the same statement order
7	 * so that a failure part-way through produces the same traceback - the
8	 * `atSourceLine` numbers are the line numbers of the corresponding statements
9	 * in the Python source, which the frozen build reports on error.
10	 *
11	 * Usage:
12	 *   node test17.mjs --a INT --b INT --c STR --d INT --e STR --f INT --g INT
13	 */
14	
15	import { ArgumentParser, HelpRequested, ParserError, int, str } from './lib/argparse/index.mjs';
16	import { Bytes, Int8ul, Int16ul } from './lib/construct/index.mjs';
17	import { PyException } from './lib/python/exceptions.mjs';
18	import { encodeUtf8 } from './lib/python/codec.mjs';
19	import { pyMod } from './lib/python/int.mjs';
20	import { pyBytesRepr } from './lib/python/repr.mjs';
21	import { getPythonArgv } from './lib/runtime/argv.mjs';
22	import { PROG_NAME } from './lib/runtime/config.mjs';
23	import { flush, printLine, writeStderr, writeStdout } from './lib/runtime/stdio.mjs';
24	import { atSourceLine, renderTraceback } from './lib/runtime/traceback.mjs';
25	
26	const BYTE_MODULUS = 256n;
27	
28	function buildParser() {
29	  const parser = new ArgumentParser(PROG_NAME);
30	  parser.addArgument(['--a'], { type: int, required: true });
31	  parser.addArgument(['--b'], { type: int, required: true });
32	  parser.addArgument(['--c'], { type: str, required: true });
33	  parser.addArgument(['--d'], { type: int, required: true });
34	  parser.addArgument(['--e'], { type: str, required: true });
35	  parser.addArgument(['--f'], { type: int, required: true });
36	  parser.addArgument(['--g'], { type: int, required: true });
37	  return parser;
38	}
39	
40	function main() {
41	  const args = buildParser().parseArgs(getPythonArgv());
42	
43	  const format1 = atSourceLine(16, () => Int8ul.build(args.a)); // 构建头字节
44	  const format2 = atSourceLine(17, () => Int16ul.build(args.b)); // 构建长度字段
45	  const format3 = atSourceLine(18, () => Bytes(args.d).build(encodeUtf8(args.c))); // 构建第一个数据块
46	  const format4 = atSourceLine(19, () => Int8ul.build(args.f)); // 构建分隔符
47	  const format5 = atSourceLine(20, () => Bytes(args.g).build(encodeUtf8(args.e))); // 构建第二个数据块
48	  // 构建校验和，确保在字节范围内
49	  const format6 = atSourceLine(21, () => Int8ul.build(pyMod(args.f + args.g, BYTE_MODULUS)));
50	  // 构建最终校验，确保在字节范围内
51	  const format7 = atSourceLine(22, () => Int8ul.build(pyMod(args.a + args.b, BYTE_MODULUS)));
52	
53	  printLine(pyBytesRepr(format1));
54	  printLine(pyBytesRepr(format2));
55	  printLine(pyBytesRepr(format3));
56	  printLine(pyBytesRepr(format4));
57	  printLine(pyBytesRepr(format5));
58	  printLine(pyBytesRepr(format6));
59	  printLine(pyBytesRepr(format7));
60	}
61	
62	try {
63	  main();
64	  flush(0);
65	} catch (err) {
66	  if (err instanceof HelpRequested) {
67	    writeStdout(err.text);
68	    flush(0);
69	  } else if (err instanceof ParserError) {
70	    writeStderr(err.render());
71	    flush(2);
72	  } else if (err instanceof PyException) {
73	    writeStderr(renderTraceback(err));
74	    flush(1);
75	  } else {
76	    throw err;
77	  }
78	}
