1	#!/usr/bin/env node
2	/**
3	 * Differential harness: run the reference executable and the Node port with
4	 * identical argv and compare stdout, stderr and exit code byte for byte.
5	 *
6	 * The PyInstaller banner embeds the process id, so that one number is
7	 * normalised before comparing. Everything else must match exactly.
8	 */
9	
10	import { spawnSync } from 'node:child_process';
11	
12	const EXE = '/workspace/dataset/test17_executable';
13	const PORT = ['/output/test17.mjs'];
14	
15	const normalise = (text) => text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
16	
17	export function runPair(argv) {
18	  const a = spawnSync(EXE, argv, { encoding: 'latin1', maxBuffer: 1 << 26 });
19	  const b = spawnSync(process.execPath, [...PORT, ...argv], { encoding: 'latin1', maxBuffer: 1 << 26 });
20	  return {
21	    argv,
22	    ok: a.stdout === b.stdout
23	      && normalise(a.stderr) === normalise(b.stderr)
24	      && a.status === b.status,
25	    ref: { stdout: a.stdout, stderr: normalise(a.stderr), status: a.status },
26	    port: { stdout: b.stdout, stderr: normalise(b.stderr), status: b.status },
27	  };
28	}
29	
30	function show(result) {
31	  const { ref, port } = result;
32	  console.log(`\nMISMATCH argv=${JSON.stringify(result.argv)}`);
33	  if (ref.stdout !== port.stdout) {
34	    console.log(`  stdout ref : ${JSON.stringify(ref.stdout)}`);
35	    console.log(`  stdout port: ${JSON.stringify(port.stdout)}`);
36	  }
37	  if (ref.stderr !== port.stderr) {
38	    console.log(`  stderr ref : ${JSON.stringify(ref.stderr)}`);
39	    console.log(`  stderr port: ${JSON.stringify(port.stderr)}`);
40	  }
41	  if (ref.status !== port.status) {
42	    console.log(`  exit ref=${ref.status} port=${port.status}`);
43	  }
44	}
45	
46	/** @param {string[][]} cases */
47	export function compareAll(cases, label = 'cases') {
48	  let pass = 0;
49	  const failures = [];
50	  for (const argv of cases) {
51	    const result = runPair(argv);
52	    if (result.ok) pass += 1;
53	    else failures.push(result);
54	  }
55	  for (const failure of failures) show(failure);
56	  console.log(`\n${label}: ${pass}/${cases.length} match, ${failures.length} mismatch`);
57	  return failures.length;
58	}
