import { runPair } from '/tmp/diffharness.mjs';

const base = { a: '1', b: '2', c: 'abc', d: '3', e: 'de', f: '4', g: '2' };
function mk(over = {}) {
  const o = { ...base, ...over };
  return ['--a', o.a, '--b', o.b, '--c', o.c, '--d', o.d, '--e', o.e, '--f', o.f, '--g', o.g];
}

const cases = [];
// Int8ul out of range at --a
cases.push(mk({ a: '256' }));
cases.push(mk({ a: '-1' }));
cases.push(mk({ a: '99999999999999999999999' }));
// Int16ul out of range at --b
cases.push(mk({ b: '65536' }));
cases.push(mk({ b: '-1' }));
// Bytes length mismatch --c/--d
cases.push(mk({ c: 'abc', d: '4' }));
cases.push(mk({ c: 'abc', d: '2' }));
cases.push(mk({ c: 'abc', d: '-1' }));
cases.push(mk({ c: 'abc', d: '-5' }));
// Int8ul out of range at --f
cases.push(mk({ f: '256' }));
cases.push(mk({ f: '-3' }));
// Bytes --e/--g
cases.push(mk({ e: 'de', g: '3' }));
cases.push(mk({ e: 'de', g: '-1' }));
// huge d
cases.push(mk({ d: '10000000000000000000000000000000' }));
cases.push(mk({ d: '-10000000000000000000000000000000' }));
cases.push(mk({ g: '10000000000000000000000000000000' }));
// several problems at once
cases.push(mk({ a: '256', b: '65536', d: '-1', f: '300', g: '-2' }));
cases.push(mk({ b: '65536', d: '-1' }));
cases.push(mk({ d: '9', f: '999' }));
// f+g overflow into format6 (should be fine due to mod)
cases.push(mk({ f: '200', g: '2', e: 'xy' }));
// empty c with d 0
cases.push(mk({ c: '', d: '0' }));
cases.push(mk({ c: '', d: '1' }));
// non-ascii c multibyte length
cases.push(mk({ c: 'é', d: '1' }));
cases.push(mk({ c: 'é', d: '2' }));
cases.push(mk({ c: '😀', d: '4' }));
cases.push(mk({ c: '😀', d: '3' }));
// missing args / bad ints
cases.push(['--a', '1']);
cases.push(mk({ a: 'x' }));
cases.push(mk({ d: 'x' }));
cases.push(['--help']);
cases.push([]);

let bad = 0;
for (const argv of cases) {
  const r = runPair(argv);
  if (!r.ok) {
    bad++;
    console.log('MISMATCH', JSON.stringify(argv));
    console.log('  ref  out=', JSON.stringify(r.ref.stdout), 'st=', r.ref.status);
    console.log('  port out=', JSON.stringify(r.port.stdout), 'st=', r.port.status);
    if (r.ref.stderr !== r.port.stderr) {
      console.log('  ref  err=', JSON.stringify(r.ref.stderr));
      console.log('  port err=', JSON.stringify(r.port.stderr));
    }
  }
}
console.log(`p1: ${cases.length - bad}/${cases.length} match`);

