/**
 * Raw-byte differential harness: arguments are given as arrays of byte values
 * (0-255) so we can pass sequences that are not valid UTF-8.
 */
import { spawnSync } from 'node:child_process';
import { readFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';

const EXE = '/workspace/dataset/test17_executable';
const dir = mkdtempSync(`${tmpdir()}/rawcmp-`);

const normalise = (t) => t.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

/** @param {number[]} bytes -> a bash `printf %b` format string */
function toPrintf(bytes) {
  let s = '';
  for (const b of bytes) s += `\\0${b.toString(8).padStart(3, '0')}`;
  return s;
}

/** @param {(string|number[])[]} argv each entry: JS string (ascii) or byte array */
export function runPairRaw(argv) {
  const byteArgs = argv.map((a) => (typeof a === 'string'
    ? [...Buffer.from(a, 'utf8')]
    : a));
  const assigns = byteArgs
    .map((b, i) => `v${i}=$(printf '%b' '${toPrintf(b)}')`)
    .join('\n');
  const refs = byteArgs.map((_, i) => `"$v${i}"`).join(' ');
  const script = `${assigns}
${EXE} ${refs} > ${dir}/o.ref 2> ${dir}/e.ref; echo $? > ${dir}/s.ref
${process.execPath} /output/test17.mjs ${refs} > ${dir}/o.port 2> ${dir}/e.port; echo $? > ${dir}/s.port
`;
  const res = spawnSync('/bin/bash', ['-c', script], { encoding: 'latin1' });
  if (res.status !== 0) throw new Error(`harness failed: ${res.stderr}`);
  const rd = (f) => readFileSync(`${dir}/${f}`, 'latin1');
  const ref = { stdout: rd('o.ref'), stderr: normalise(rd('e.ref')), status: Number(rd('s.ref').trim()) };
  const port = { stdout: rd('o.port'), stderr: normalise(rd('e.port')), status: Number(rd('s.port').trim()) };
  return {
    argv: byteArgs,
    ok: ref.stdout === port.stdout && ref.stderr === port.stderr && ref.status === port.status,
    ref,
    port,
  };
}

export function label(argv) {
  return argv.map((a) => (typeof a === 'string' ? a : `<${a.map((b) => b.toString(16).padStart(2, '0')).join(' ')}>`)).join(' ');
}

