  1	/**
  2	 * A faithful subset of Python's argparse.ArgumentParser.
  3	 *
  4	 * Only what test17.py exercises is modelled: long options that each take one
  5	 * value, the implicit -h/--help, and required-argument checking. The parsing
  6	 * order and error precedence follow CPython's _parse_known_args so that
  7	 * diagnostics come out in the same order for the same input.
  8	 */
  9	
 10	import { pyStrRepr } from '../python/repr.mjs';
 11	import { PyException } from '../python/exceptions.mjs';
 12	import { HelpRequested, ParserError } from './exceptions.mjs';
 13	import { formatHelp, formatUsage } from './formatter.mjs';
 14	
 15	// argparse's _negative_number_matcher. Python's \d is Unicode-aware, so
 16	// non-ASCII decimal digits count here too.
 17	const NEGATIVE_NUMBER = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;
 18	
 19	const PREFIX_CHARS = '-';
 20	
 21	// Token classes, matching the characters argparse uses in arg_strings_pattern.
 22	const OPTION = 'O';
 23	const VALUE = 'A';
 24	const SEPARATOR = '-';
 25	
 26	/** How argparse names an action in an error message. */
 27	function actionName(action) {
 28	  return action.optionStrings.join('/');
 29	}
 30	
 31	export class ArgumentParser {
 32	  constructor(prog) {
 33	    this.prog = prog;
 34	    this.actions = [];
 35	    this.optionStringActions = new Map();
 36	
 37	    this.addArgument(['-h', '--help'], {
 38	      nargs: 0,
 39	      dest: 'help',
 40	      help: 'show this help message and exit',
 41	    });
 42	  }
 43	
 44	  addArgument(optionStrings, options = {}) {
 45	    const dest = options.dest ?? optionStrings[optionStrings.length - 1].replace(/^-+/, '');
 46	    const action = {
 47	      optionStrings,
 48	      dest,
 49	      nargs: options.nargs ?? 1,
 50	      type: options.type ?? null,
 51	      required: options.required ?? false,
 52	      metavar: options.metavar ?? dest.toUpperCase(),
 53	      help: options.help ?? null,
 54	    };
 55	    this.actions.push(action);
 56	    for (const flag of optionStrings) this.optionStringActions.set(flag, action);
 57	    return action;
 58	  }
 59	
 60	  formatUsage() {
 61	    return formatUsage(this.prog, this.actions);
 62	  }
 63	
 64	  formatHelp() {
 65	    return formatHelp(this.prog, this.actions);
 66	  }
 67	
 68	  error(message) {
 69	    throw new ParserError(this.formatUsage(), this.prog, message);
 70	  }
 71	
 72	  /**
 73	   * Classify one argv token. Returns null when it is a plain value, otherwise
 74	   * a tuple describing which option it names (action === null for an option
 75	   * the parser does not know).
 76	   *
 77	   * `sep` records how an inline value was attached: '=' for --opt=value, ''
 78	   * for a value glued onto a short flag, null when there is no inline value.
 79	   * argparse consults it to decide whether a glued value on a zero-argument
 80	   * flag is an error or a run of further short flags.
 81	   */
 82	  parseOptional(argString) {
 83	    if (argString === '') return null;
 84	    if (!PREFIX_CHARS.includes(argString[0])) return null;
 85	
 86	    const exact = this.optionStringActions.get(argString);
 87	    if (exact) {
 88	      return { action: exact, optionString: argString, explicitArg: null, sep: null };
 89	    }
 90	
 91	    if (argString.length === 1) return null; // a bare "-" is a value
 92	
 93	    if (argString.includes('=')) {
 94	      const splitAt = argString.indexOf('=');
 95	      const optionString = argString.slice(0, splitAt);
 96	      const known = this.optionStringActions.get(optionString);
 97	      if (known) {
 98	        return {
 99	          action: known,
100	          optionString,
101	          explicitArg: argString.slice(splitAt + 1),
102	          sep: '=',
103	        };
104	      }
105	    }
106	
107	    const matches = this.getOptionTuples(argString);
108	    if (matches.length > 1) {
109	      const names = matches.map((match) => match.optionString).join(', ');
110	      this.error(`ambiguous option: ${argString} could match ${names}`);
111	    }
112	    if (matches.length === 1) return matches[0];
113	
114	    // Nothing matched. A token that merely looks like a negative number is a
115	    // value, because no option string here looks like one.
116	    if (NEGATIVE_NUMBER.test(argString)) return null;
117	    if (argString.includes(' ')) return null;
118	
119	    return { action: null, optionString: argString, explicitArg: null, sep: null };
120	  }
121	
122	  /** Unambiguous-prefix matching, e.g. "--he" -> "--help". */
123	  getOptionTuples(argString) {
124	    const matches = [];
125	
126	    if (PREFIX_CHARS.includes(argString[1])) {
127	      const splitAt = argString.indexOf('=');
128	      const prefix = splitAt >= 0 ? argString.slice(0, splitAt) : argString;
129	      const explicitArg = splitAt >= 0 ? argString.slice(splitAt + 1) : null;
130	      const sep = splitAt >= 0 ? '=' : null;
131	      for (const [flag, action] of this.optionStringActions) {
132	        if (flag.startsWith(prefix)) {
133	          matches.push({ action, optionString: flag, explicitArg, sep });
134	        }
135	      }
136	      return matches;
137	    }
138	
139	    // Single-dash: either an exact short option with the rest glued on as its
140	    // value, or a prefix of a longer option string.
141	    const shortPrefix = argString.slice(0, 2);
142	    const shortExplicitArg = argString.slice(2);
143	    for (const [flag, action] of this.optionStringActions) {
144	      if (flag === shortPrefix) {
145	        matches.push({ action, optionString: flag, explicitArg: shortExplicitArg, sep: '' });
146	      } else if (flag.startsWith(argString)) {
147	        matches.push({ action, optionString: flag, explicitArg: null, sep: null });
148	      }
149	    }
150	    return matches;
151	  }
152	
153	  /** Apply an action's `type` callable, mapping ValueError to a usage error. */
154	  getValue(action, optionString, text) {
155	    if (!action.type) return text;
156	    try {
157	      return action.type.convert(text);
158	    } catch (err) {
159	      if (err instanceof PyException) {
160	        this.error(
161	          `argument ${optionString}: invalid ${action.type.name} value: ${pyStrRepr(text)}`,
162	        );
163	      }
164	      throw err;
165	    }
166	  }
167	
168	  /**
169	   * Consume the option at `start` and return the next index to look at.
170	   *
171	   * The loop exists for glued short flags: "-h5" names the zero-argument -h
172	   * and leaves "5" over, which argparse re-reads as "-5". If that names
173	   * another flag the loop continues; if not, the leftover is set aside as an
174	   * unrecognised argument rather than being an error outright.
175	   */
176	  consumeOptional(start, argStrings, pattern, tuples, namespace, extras) {
177	    let { action, optionString, explicitArg, sep } = tuples[start];
178	    const pending = [];
179	    let stop = start + 1;
180	
181	    for (;;) {
182	      if (action === null) {
183	        extras.push(argStrings[start]);
184	        return start + 1;
185	      }
186	
187	      if (explicitArg !== null) {
188	        const takesNoValue = action.nargs === 0;
189	
190	        if (takesNoValue && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
191	          if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
192	            this.error(
193	              `argument ${actionName(action)}: ignored explicit argument ${pyStrRepr(explicitArg)}`,
194	            );
195	          }
196	          pending.push({ action, optionString });
197	
198	          const next = optionString[0] + explicitArg[0];
199	          const nextAction = this.optionStringActions.get(next);
200	          if (!nextAction) {
201	            extras.push(optionString[0] + explicitArg);
202	            break;
203	          }
204	          action = nextAction;
205	          optionString = next;
206	          explicitArg = explicitArg.slice(1);
207	          if (explicitArg === '') {
208	            sep = null;
209	            explicitArg = null;
210	          } else if (explicitArg[0] === '=') {
211	            sep = '=';
212	            explicitArg = explicitArg.slice(1);
213	          } else {
214	            sep = '';
215	          }
216	          continue;
217	        }
218	
219	        if (takesNoValue) {
220	          this.error(
221	            `argument ${actionName(action)}: ignored explicit argument ${pyStrRepr(explicitArg)}`,
222	          );
223	        }
224	        pending.push({ action, optionString, raw: explicitArg });
225	        break;
226	      }
227	
228	      if (action.nargs === 0) {
229	        pending.push({ action, optionString });
230	        break;
231	      }
232	
233	      // Only a plain value token can satisfy the option. A "--" separator sits
234	      // at a distinct pattern position and is deliberately not a candidate.
235	      if (pattern[start + 1] === VALUE) {
236	        pending.push({ action, optionString, raw: argStrings[start + 1] });
237	        stop = start + 2;
238	        break;
239	      }
240	      this.error(`argument ${optionString}: expected one argument`);
241	    }
242	
243	    // Actions run only after the whole token has been decomposed, which is why
244	    // "-h5" still prints help despite leaving an unrecognised "-5" behind.
245	    for (const item of pending) this.takeAction(item, namespace);
246	    return stop;
247	  }
248	
249	  takeAction({ action, optionString, raw }, namespace) {
250	    if (action.nargs === 0) {
251	      if (action.dest === 'help') throw new HelpRequested(this.formatHelp());
252	      namespace[action.dest] = true;
253	      return;
254	    }
255	    namespace[action.dest] = this.getValue(action, optionString, raw);
256	  }
257	
258	  /** @returns {[Record<string, unknown>, string[]]} namespace and leftovers */
259	  parseKnownArgs(argStrings) {
260	    // Pass one: classify every token, mirroring argparse's arg_strings_pattern.
261	    // "--" gets its own marker rather than being lumped in with plain values,
262	    // because an option may not take it as an argument. Everything following
263	    // the first "--" is an ordinary value.
264	    const tuples = [];
265	    const pattern = [];
266	    let afterDoubleDash = false;
267	    for (const argString of argStrings) {
268	      if (afterDoubleDash) {
269	        tuples.push(null);
270	        pattern.push(VALUE);
271	      } else if (argString === '--') {
272	        afterDoubleDash = true;
273	        tuples.push(null);
274	        pattern.push(SEPARATOR);
275	      } else {
276	        const tuple = this.parseOptional(argString);
277	        tuples.push(tuple);
278	        pattern.push(tuple === null ? VALUE : OPTION);
279	      }
280	    }
281	
282	    // Pass two: consume options left to right. With no positionals declared,
283	    // every token no option claims falls through to `extras`.
284	    const namespace = Object.create(null);
285	    const extras = [];
286	    let i = 0;
287	    while (i < argStrings.length) {
288	      if (pattern[i] !== OPTION) {
289	        extras.push(argStrings[i]);
290	        i += 1;
291	        continue;
292	      }
293	      i = this.consumeOptional(i, argStrings, pattern, tuples, namespace, extras);
294	    }
295	
296	    // Required options are reported together, in declaration order.
297	    const missing = this.actions
298	      .filter((action) => action.required && !(action.dest in namespace))
299	      .map(actionName);
300	    if (missing.length) {
301	      this.error(`the following arguments are required: ${missing.join(', ')}`);
302	    }
303	
304	    return [namespace, extras];
305	  }
306	
307	  parseArgs(argStrings) {
308	    const [namespace, extras] = this.parseKnownArgs(argStrings);
309	    if (extras.length) {
310	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
311	    }
312	    return namespace;
313	  }
314	}
315	/**
316	 * argparse's HelpFormatter, reduced to the layout this parser needs:
317	 * a single "options:" section of store/help actions with no positionals.
318	 */
319	
320	const INDENT = '  ';
321	const MAX_HELP_POSITION = 24;
322	
323	/** "--a A" / "-h, --help" - the left-hand column for an action. */
324	export function formatInvocation(action) {
325	  if (action.nargs === 0) return action.optionStrings.join(', ');
326	  return action.optionStrings.map((flag) => `${flag} ${action.metavar}`).join(', ');
327	}
328	
329	/** How an action appears inside the usage line, bracketed when optional. */
330	function formatUsagePart(action) {
331	  const body = action.nargs === 0
332	    ? action.optionStrings[0]
333	    : `${action.optionStrings[0]} ${action.metavar}`;
334	  return action.required ? body : `[${body}]`;
335	}
336	
337	/** "usage: prog [-h] --a A ...\n" */
338	export function formatUsage(prog, actions) {
339	  const parts = actions.map(formatUsagePart);
340	  return `usage: ${[prog, ...parts].join(' ')}\n`;
341	}
342	
343	/**
344	 * The full --help text. Help strings line up in a second column whose offset
345	 * argparse derives from the widest invocation, capped at MAX_HELP_POSITION.
346	 */
347	export function formatHelp(prog, actions) {
348	  const invocations = actions.map(formatInvocation);
349	  const widest = invocations.reduce(
350	    (max, text) => Math.max(max, text.length + INDENT.length),
351	    0,
352	  );
353	  const helpPosition = Math.min(widest + 2, MAX_HELP_POSITION);
354	
355	  let out = `${formatUsage(prog, actions)}\noptions:\n`;
356	  actions.forEach((action, index) => {
357	    const invocation = invocations[index];
358	    if (!action.help) {
359	      // Actions without help text contribute the invocation line alone, with
360	      // no trailing padding.
361	      out += `${INDENT}${invocation}\n`;
362	      return;
363	    }
364	    const padding = helpPosition - INDENT.length - invocation.length;
365	    out += `${INDENT}${invocation}${' '.repeat(Math.max(padding, 1))}${action.help}\n`;
366	  });
367	  return out;
368	}
369	/**
370	 * Control-flow signals raised by ArgumentParser.
371	 *
372	 * The real argparse writes to a stream and calls sys.exit() from inside
373	 * parse_args(). Keeping that as data lets the entry point own all I/O.
374	 */
375	
376	/** Raised for -h/--help: print `text` to stdout and exit 0. */
377	export class HelpRequested {
378	  constructor(text) {
379	    this.text = text;
380	  }
381	}
382	
383	/** Raised for a usage error: print usage + message to stderr and exit 2. */
384	export class ParserError {
385	  constructor(usage, prog, message) {
386	    this.usage = usage;
387	    this.prog = prog;
388	    this.message = message;
389	  }
390	
391	  render() {
392	    return `${this.usage}${this.prog}: error: ${this.message}\n`;
393	  }
394	}

