import { runPairRaw, label } from '/tmp/rawcmp.mjs';

const B = (s) => [...Buffer.from(s, 'latin1')];
const cases = [];
const mk = (o) => ['--a', o.a ?? '1', '--b', o.b ?? '1', '--c', o.c ?? '', '--d', o.d ?? '0',
  '--e', o.e ?? '', '--f', o.f ?? '0', '--g', o.g ?? '0', ...(o.extra ?? [])];

// single invalid bytes in --c
for (const b of [0xff, 0xfe, 0x80, 0xc3, 0xc0, 0xc1, 0xf5, 0xf8, 0xfc, 0x8f, 0xbf, 0xe0, 0xf0, 0xf4]) {
  cases.push(mk({ c: [b], d: '1' }));
}
// runs
cases.push(mk({ c: [0xff, 0xfe], d: '2' }));
cases.push(mk({ c: [0xc0, 0x80], d: '2' }));
cases.push(mk({ c: [0xed, 0xa0, 0x80], d: '3' }));
cases.push(mk({ c: [0xf5, 0x80, 0x80, 0x80], d: '4' }));
cases.push(mk({ c: [0xf0, 0x9f], d: '2' }));
cases.push(mk({ c: [0xe1, 0x80], d: '2' }));
cases.push(mk({ c: [0xe0, 0xa0], d: '2' }));
cases.push(mk({ c: [0xc2], d: '1' }));
cases.push(mk({ c: [0xf0, 0x9f, 0x98], d: '3' }));
cases.push(mk({ c: [0xf0, 0x80, 0x80, 0x80], d: '4' }));
cases.push(mk({ c: [0xe0, 0x80, 0x80], d: '3' }));
// invalid at non-zero positions, after astral char
cases.push(mk({ c: [0x61, 0x62, 0xff], d: '3' }));
cases.push(mk({ c: [0xf0, 0x9f, 0x98, 0x80, 0xff], d: '5' })); // astral then bad
cases.push(mk({ c: [0xf0, 0x9f, 0x98, 0x80, 0xff, 0xfe], d: '6' }));
cases.push(mk({ c: [0xc3, 0xa9, 0xff], d: '3' })); // e-acute then bad
cases.push(mk({ c: [0x61, 0xff, 0x62, 0xff], d: '4' }));
// same in --e
for (const b of [0xff, 0x80, 0xc3]) cases.push(mk({ e: [b], g: '1' }));
cases.push(mk({ e: [0xf0, 0x9f, 0x98, 0x80, 0xff], g: '5' }));
cases.push(mk({ e: [0xed, 0xa0, 0x80], g: '3' }));
// both c and e bad -> c wins (line 18)
cases.push(mk({ c: [0xff], e: [0xfe], d: '1', g: '1' }));
// bad bytes in integer options
for (const b of [0xff, 0x80, 0xc3]) {
  cases.push(mk({ a: [b] }));
  cases.push(mk({ d: [b] }));
  cases.push(mk({ g: [0x31, b] }));
}
cases.push(mk({ a: [0xf0, 0x9f, 0x98, 0x80] }));
cases.push(mk({ a: [0xed, 0xa0, 0x80] }));
// bad bytes in unknown option / extras
cases.push(mk({ extra: [[0x2d, 0x2d, 0xff]] }));
cases.push(mk({ extra: [[0xff]] }));
cases.push(mk({ extra: [[0x2d, 0x2d, 0x7a], [0xff, 0xfe]] }));
cases.push(mk({ extra: [[0x2d, 0x2d, 0x61, 0x3d, 0xff]] })); // --a=<ff>
// bad bytes with also out-of-range --a (which wins?)
cases.push(mk({ a: '256', c: [0xff], d: '1' }));
cases.push(mk({ a: '1', b: '65536', c: [0xff], d: '1' }));
cases.push(mk({ c: [0xff], d: '-1' }));
cases.push(mk({ c: 'x', d: '-1', e: [0xff], g: '1' }));

let bad = 0;
for (const argv of cases) {
  const r = runPairRaw(argv);
  if (!r.ok) {
    bad++;
    console.log('MISMATCH', label(argv));
    console.log('  ref  st=' + r.ref.status, 'out=' + JSON.stringify(r.ref.stdout));
    console.log('  port st=' + r.port.status, 'out=' + JSON.stringify(r.port.stdout));
    if (r.ref.stderr !== r.port.stderr) {
      console.log('  ref  err=' + JSON.stringify(r.ref.stderr));
      console.log('  port err=' + JSON.stringify(r.port.stderr));
    }
  }
}
console.log(`raw1: ${cases.length - bad}/${cases.length} match`);

import { runPairRaw, label } from '/tmp/rawcmp.mjs';

