const mk = (o = {}) => ['--a', o.a ?? '1', '--b', o.b ?? '1', '--c', o.c ?? '', '--d', o.d ?? '0',
  '--e', o.e ?? '', '--f', o.f ?? '0', '--g', o.g ?? '0', ...(o.extra ?? [])];

// valid non-ASCII in extras -> is stderr utf-8 or ascii?
cases.push(mk({ extra: [[0xc3, 0xa9]] }));                      // é
cases.push(mk({ extra: [[0xe2, 0x82, 0xac]] }));                // €
cases.push(mk({ extra: [[0xf0, 0x9f, 0x98, 0x80]] }));          // astral
cases.push(mk({ extra: [[0x2d, 0x2d, 0xc3, 0xa9]] }));          // --é unknown option
// non-ASCII in int repr messages
cases.push(mk({ a: [0xc3, 0xa9] }));
cases.push(mk({ a: [0xf0, 0x9f, 0x98, 0x80] }));
cases.push(mk({ a: [0xe2, 0x82, 0xac, 0x31] }));
cases.push(mk({ a: [0xd9, 0xa5] }));                            // arabic-indic 5 -> valid int 5
cases.push(mk({ a: [0xd9, 0xa5, 0xd9, 0xa6] }));                // 56
cases.push(mk({ a: [0xc2, 0x85, 0x31] }));                      // NEL + 1
cases.push(mk({ a: [0xc2, 0xa0, 0x31] }));                      // NBSP + 1
cases.push(mk({ a: [0x1c, 0x31] }));                            // FS + 1 -> invalid
// missing value / expected one argument
cases.push(['--a']);
cases.push(['--a', '1', '--b']);
cases.push(['--a', '1', '--b', '2', '--c']);
cases.push(['--a', '--b', '1']);
// -- separator
cases.push(['--a', '1', '--b', '2', '--c', 'x', '--d', '1', '--e', '', '--f', '0', '--g', '0', '--']);
cases.push(['--a', '--', '1']);
// ambiguous / prefix
cases.push(['--h']);
cases.push(['-h']);
cases.push(['-h5']);
cases.push(['--help=x']);
cases.push(['-x']);
cases.push(['-']);
cases.push(['---a', '1']);
// duplicate options, last wins
cases.push(mk({ extra: ['--c', 'zz', '--d', '2'] }));
// construct extremes
cases.push(mk({ a: '-99999999999999999999999' }));
cases.push(mk({ b: '-99999999999999999999999' }));
cases.push(mk({ d: '-99999999999999999999999', c: 'ab' }));
cases.push(mk({ g: '-99999999999999999999999', e: 'ab' }));
cases.push(mk({ f: '-99999999999999999999999' }));
cases.push(mk({ d: '99999999999999999999999', c: 'ab' }));
cases.push(mk({ g: '99999999999999999999999', e: 'ab' }));
cases.push(mk({ f: '255', g: '1', e: 'x' }));
cases.push(mk({ f: '255', g: '256', e: 'x'.repeat(256) }));
cases.push(mk({ a: '255', b: '65535' }));
cases.push(mk({ d: '0', c: 'a' }));
// negative modulus results
cases.push(mk({ f: '0', g: '-256', e: '' }));
// f valid, g negative -> Bytes(g) negative at line 20
cases.push(mk({ f: '1', g: '-1', e: '' }));
cases.push(mk({ f: '1', g: '-1', e: 'abc' }));
// d negative and c wrong length -> negative wins
cases.push(mk({ d: '-1', c: 'abcdef' }));
// int values with underscores/plus
cases.push(mk({ a: '+256' }));
cases.push(mk({ a: '2_5_6' }));
cases.push(mk({ a: '1_' }));
cases.push(mk({ d: '+3', c: 'abc' }));

let bad = 0;
for (const argv of cases) {
  const r = runPairRaw(argv);
  if (!r.ok) {
    bad++;
    console.log('MISMATCH', label(argv));
    if (r.ref.stdout !== r.port.stdout) {
      console.log('  ref  out=' + JSON.stringify(r.ref.stdout));
      console.log('  port out=' + JSON.stringify(r.port.stdout));
    }
    if (r.ref.stderr !== r.port.stderr) {
      console.log('  ref  err=' + JSON.stringify(r.ref.stderr));
      console.log('  port err=' + JSON.stringify(r.port.stderr));
    }
    if (r.ref.status !== r.port.status) console.log(`  exit ref=${r.ref.status} port=${r.port.status}`);
  }
}
console.log(`raw2: ${cases.length - bad}/${cases.length} match`);

