input.content:
import { runPairRaw, label } from '/tmp/rawcmp.mjs';

const cases = [];
// ambiguous option paths, incl. raw bytes
cases.push(['--=x']);
cases.push(['--=', '1']);
cases.push([[0x2d, 0x2d, 0x3d, 0xff]]);
cases.push([[0x2d, 0x2d, 0x3d, 0xff, 0xfe]]);
cases.push(['--a', '1', '--b', '2', '--c', 'x', '--d', '1', '--e', '', '--f', '0', '--g', '0', '--=z']);
// option value that looks like an option
cases.push(['--c', '--d']);
cases.push(['--a', '-1', '--b', '1', '--c', '', '--d', '0', '--e', '', '--f', '0', '--g', '0']);
cases.push(['--a', '-256', '--b', '1', '--c', '', '--d', '0', '--e', '', '--f', '0', '--g', '0']);
cases.push(['--a', '--a']);
// inline = with bad bytes
cases.push(['--a=1', '--b=1', [0x2d, 0x2d, 0x63, 0x3d, 0xff], '--d=1', '--e=', '--f=0', '--g=0']);
cases.push(['--a=1', '--b=1', '--c=', '--d=0', [0x2d, 0x2d, 0x65, 0x3d, 0xff, 0xfe], '--f=0', '--g=2']);
cases.push([[0x2d, 0x2d, 0x61, 0x3d, 0xff], '--b=1', '--c=', '--d=0', '--e=', '--f=0', '--g=0']);
// -- separator then bad bytes
cases.push(['--a', '1', '--b', '1', '--c', '', '--d', '0', '--e', '', '--f', '0', '--g', '0', '--', [0xff]]);
// duplicate --c, first bad
cases.push(['--a', '1', '--b', '1', '--c', [0xff], '--c', 'ab', '--d', '2', '--e', '', '--f', '0', '--g', '0']);
cases.push(['--a', '1', '--b', '1', '--c', 'ab', '--c', [0xff], '--d', '1', '--e', '', '--f', '0', '--g', '0']);
// unknown single-dash options with bad bytes
cases.push([[0x2d, 0xff]]);
cases.push([[0x2d, 0x68, 0xff]]);
cases.push([[0x2d, 0x2d, 0x68, 0xff]]);
// bad bytes making a token look like negative number
cases.push([[0x2d, 0xd9, 0xa5]]);  // -٥  (unicode digit) -> negative number matcher
cases.push([[0x2d, 0xd9, 0xa5], '--a', '1']);
// huge but under digit limit
cases.push(['--a', '1', '--b', '1', '--c', 'ab', '--d', `1${'0'.repeat(1000)}`, '--e', '', '--f', '0', '--g', '0']);
cases.push(['--a', `1${'0'.repeat(1000)}`, '--b', '1', '--c', '', '--d', '0', '--e', '', '--f', '0', '--g', '0']);
cases.push(['--a', '1', '--b', '1', '--c', '', '--d', '0', '--e', '', '--f', '0', '--g', `-1${'0'.repeat(1000)}`]);
// long payload
cases.push(['--a', '1', '--b', '1', '--c', 'x'.repeat(5000), '--d', '4999', '--e', '', '--f', '0', '--g', '0']);
cases.push(['--a', '1', '--b', '1', '--c', 'x'.repeat(5000), '--d', '5000', '--e', '', '--f', '0', '--g', '0']);

let bad = 0;
for (const argv of cases) {
  const r = runPairRaw(argv);
  if (!r.ok) {
    bad++;
    console.log('MISMATCH', label(argv).slice(0, 200));
    if (r.ref.stdout !== r.port.stdout) {
      console.log('  ref  out=' + JSON.stringify(r.ref.stdout.slice(0, 300)));
      console.log('  port out=' + JSON.stringify(r.port.stdout.slice(0, 300)));
    }
    if (r.ref.stderr !== r.port.stderr) {
      console.log('  ref  err=' + JSON.stringify(r.ref.stderr.slice(0, 400)));
      console.log('  port err=' + JSON.stringify(r.port.stderr.slice(0, 400)));
    }
    if (r.ref.status !== r.port.status) console.log(`  exit ref=${r.ref.status} port=${r.port.status}`);
  }
}
console.log(`raw3: ${cases.length - bad}/${cases.length} match`);

import { runPairRaw, label } from '/tmp/rawcmp.mjs';

const rnd = (n) => Math.floor(Math.random() * n);
let seed = 12345;
function rand() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }
const pick = (arr) => arr[Math.floor(rand() * arr.length)];

const intVals = ['0', '1', '-1', '255', '256', '257', '65535', '65536', '-256', '3', '2', '4', '5',
  '+1', '1_0', 'x', '', ' 7 ', '1e3', '0x10', '999999999999999999999999', '-999999999999999999999999',
  '٥', ' 1', '1'];
const badByteSeqs = [[0xff], [0xfe], [0x80], [0xc3], [0xc0, 0x80], [0xed, 0xa0, 0x80],
  [0xf5, 0x80, 0x80, 0x80], [0xf0, 0x9f], [0xe1, 0x80], [0xc2], [0xf4, 0x90, 0x80, 0x80],
  [0xf7, 0xbf, 0xbf, 0xbf], [0xfd], [0x61, 0xff, 0x62], [0xf0, 0x9f, 0x98, 0x80, 0x80]];
const strVals = ['', 'a', 'ab', 'abc', 'é', '😀', 'aé', 'zz'];

function randStr() { return rand() < 0.5 ? pick(strVals) : pick(badByteSeqs); }

const cases = [];
for (let i = 0; i < 260; i += 1) {
  const argv = ['--a', pick(intVals), '--b', pick(intVals), '--c', randStr(),
    '--d', pick(intVals), '--e', randStr(), '--f', pick(intVals), '--g', pick(intVals)];
  if (rand() < 0.12) argv.push(pick(badByteSeqs));
  if (rand() < 0.08) argv.push('--z', pick(strVals));
  cases.push(argv);
}

let bad = 0;
const seen = new Set();
for (const argv of cases) {
  const r = runPairRaw(argv);
  if (!r.ok) {
    bad++;
    const key = `${r.ref.stderr.slice(0, 200)}|${r.port.stderr.slice(0, 200)}`;
    if (seen.has(key)) continue;
    seen.add(key);
    console.log('MISMATCH', label(argv));
    if (r.ref.stdout !== r.port.stdout) {
      console.log('  ref  out=' + JSON.stringify(r.ref.stdout.slice(0, 300)));
      console.log('  port out=' + JSON.stringify(r.port.stdout.slice(0, 300)));
    }
    if (r.ref.stderr !== r.port.stderr) {
      console.log('  ref  err=' + JSON.stringify(r.ref.stderr.slice(0, 500)));
      console.log('  port err=' + JSON.stringify(r.port.stderr.slice(0, 500)));
    }
    if (r.ref.status !== r.port.status) console.log(`  exit ref=${r.ref.status} port=${r.port.status}`);
  }
}
console.log(`fuzz: ${cases.length - bad}/${cases.length} match (${seen.size} distinct signatures)`);
